const items = $input.all();
const results = [];

for (const item of items) {
  const d = item.json.body;
  const meetingTitle = d.title || 'Meeting Notes';
  const date = d.date || new Date().toISOString().split('T')[0];
  const attendees = d.attendees || [];
  const decisions = d.decisions || [];
  const actionItems = d.actionItems || [];
  const notes = d.notes || '';
  const nextMeeting = d.nextMeeting || '';

  // Build attendees list
  const attendeesList = attendees.map(a => {
    if (typeof a === 'string') return `<li>${a}</li>`;
    return `<li><strong>${a.name}</strong> (${a.email})${a.role ? ' - ' + a.role : ''}</li>`;
  }).join('');

  // Build decisions list
  const decisionsList = decisions.map((d, i) => `<li><strong>D${i + 1}:</strong> ${d}</li>`).join('');

  // Build action items table
  let actionRows = '';
  for (const action of actionItems) {
    actionRows += `<tr>
      <td style="padding:6px;border:1px solid #ddd;">${action.task || ''}</td>
      <td style="padding:6px;border:1px solid #ddd;">${action.owner || ''}</td>
      <td style="padding:6px;border:1px solid #ddd;">${action.deadline || ''}</td>
      <td style="padding:6px;border:1px solid #ddd;">${action.priority || 'normal'}</td>
    </tr>`;
  }

  const html = `<div style="font-family:Arial,sans-serif;max-width:700px;margin:auto;">
    <div style="background:#1e40af;color:white;padding:15px 20px;">
      <h2 style="margin:0;">${meetingTitle}</h2>
      <p style="margin:5px 0 0;opacity:0.9;">${date}</p>
    </div>
    <div style="padding:20px;">
      <h3>Attendees</h3>
      <ul>${attendeesList}</ul>

      ${notes ? `<h3>Notes</h3><p>${notes}</p>` : ''}

      ${decisions.length > 0 ? `<h3>Decisions Made</h3><ol>${decisionsList}</ol>` : ''}

      ${actionItems.length > 0 ? `<h3>Action Items</h3>
      <table style="width:100%;border-collapse:collapse;">
        <thead><tr style="background:#f3f4f6;"><th style="padding:6px;border:1px solid #ddd;">Task</th><th style="padding:6px;border:1px solid #ddd;">Owner</th><th style="padding:6px;border:1px solid #ddd;">Deadline</th><th style="padding:6px;border:1px solid #ddd;">Priority</th></tr></thead>
        <tbody>${actionRows}</tbody>
      </table>` : ''}

      ${nextMeeting ? `<p style="margin-top:20px;padding:10px;background:#f0fdf4;border-left:4px solid #22c55e;"><strong>Next Meeting:</strong> ${nextMeeting}</p>` : ''}
    </div>
  </div>`;

  // Extract email addresses for sending
  const emails = attendees.map(a => typeof a === 'string' ? a : a.email).filter(Boolean);

  results.push({
    json: {
      meetingTitle: meetingTitle,
      date: date,
      htmlBody: html,
      attendeeEmails: emails.join(', '),
      attendeeCount: attendees.length,
      decisionCount: decisions.length,
      actionItemCount: actionItems.length,
      sentAt: new Date().toISOString()
    }
  });
}
return results;
